(function(){
const side=$('.side-panel'),mediaNodes=[...side.children].filter(el=>el.matches('.eyebrow,.panel-title,.search,.filter-row,#mediaList,#importButton,#openVegasButton,#fileInput'));
const explorer=document.createElement('section');explorer.id='explorerPanel';explorer.hidden=true;explorer.innerHTML='<div class="eyebrow">ARCHIVOS LOCALES</div><h2>Explorer</h2><p>Explora tu equipo y añade archivos a Project Media.</p><p><button id="explorerChoose">Elegir carpeta…</button> <button id="explorerUp" disabled>↑ Subir</button></p><p id="explorerPath" style="overflow-wrap:anywhere"></p><div id="explorerFiles"></div><div id="explorerPreview"></div><p><button id="explorerImport" disabled>Añadir a Project Media</button></p><p id="explorerStatus" role="status"></p>';side.append(explorer);
const generators=document.createElement('section');generators.id='generatorsPanel';generators.hidden=true;generators.innerHTML='<div class="eyebrow">MEDIOS GENERADOS · OFFLINE</div><h2>Textos y títulos</h2><p>Crea textos, títulos, rótulos, créditos y carteles con animación. Los diseños permanecen editables en LQTS.</p><div id="generatorCatalog" class="generator-grid"></div>';side.append(generators);
const css=document.createElement('style');css.textContent='#explorerFiles{display:grid;gap:4px;max-height:230px;overflow:auto}#explorerFiles button{text-align:left;padding:8px;border:1px solid var(--line);background:#102642;color:var(--text);border-radius:5px}#explorerFiles button.selected{border-color:var(--cyan)}#explorerPreview video,#explorerPreview img{max-width:100%;max-height:180px}#explorerPreview audio{max-width:100%}.generator-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}.generator-grid button{padding:20px 14px;background:linear-gradient(145deg,#15345a,#0b1a32);border:1px solid var(--line);border-radius:9px;color:var(--text);text-align:left;cursor:pointer}.generator-grid strong{display:block;font-size:18px;margin-bottom:8px}';document.head.append(css);
let view='media',folder=null,parent=null,selected=null;
function clearPreview(){for(const m of $('#explorerPreview').querySelectorAll('video,audio')){m.pause();m.removeAttribute('src');m.load();}$('#explorerPreview').replaceChildren();}
function show(next){view=next;[...side.children].forEach(el=>el.hidden=next==='media'?!mediaNodes.includes(el):el!==(next==='explorer'?explorer:generators));stopTransitionPreview();if(next!=='explorer')clearPreview();$$('.dock-panel-item').forEach(b=>b.classList.toggle('active',$('strong',b)?.textContent.trim()==={media:'Project Media',explorer:'Explorer',generators:'Generadores'}[next]));}
async function browse(path){try{$('#explorerStatus').textContent='Leyendo carpeta…';const result=await lqtacDesktop.browseMediaFolder(path);if(result.canceled){$('#explorerStatus').textContent='Selección cancelada';return;}folder=result.folder;parent=result.parent;selected=null;clearPreview();$('#explorerPath').textContent=folder;$('#explorerUp').disabled=parent===folder;$('#explorerImport').disabled=true;$('#explorerFiles').replaceChildren();for(const entry of result.entries){const b=document.createElement('button');b.type='button';b.textContent=(entry.directory?'📁 ':'▤ ')+entry.name;if(!entry.directory&&!/^(png|jpe?g|tiff|bmp|webp)$/.test(entry.extension)){b.draggable=true;b.ondragstart=e=>{nativeMediaDrag=true;e.dataTransfer.effectAllowed='copy';e.dataTransfer.setData('application/x-lqtac-media',JSON.stringify({name:entry.name,filePath:entry.filePath,kind:/^(mp3|wav|aiff?|flac|m4a|aac|ogg)$/.test(entry.extension)?'audio':'video'}));};b.ondragend=()=>{nativeMediaDrag=false;};}b.onclick=async()=>{if(entry.directory){await browse(entry.filePath);return;}selected=entry;$('#explorerImport').disabled=false;$$('#explorerFiles button').forEach(n=>n.classList.toggle('selected',n===b));clearPreview();const kind=entry.extension.match(/^(mp3|wav|aiff?|flac|m4a|aac|ogg)$/)?'audio':entry.extension.match(/^(png|jpe?g|tiff|bmp|webp)$/)?'img':'video';const media=document.createElement(kind);if(kind!=='img')media.controls=true;media.src=await mediaUrlForTimeline(entry.filePath);if(view==='explorer'&&selected===entry)$('#explorerPreview').append(media);};$('#explorerFiles').append(b);}$('#explorerStatus').textContent=result.entries.length+' elementos'+(result.truncated?' · se muestran los primeros 5000':'');}catch(e){$('#explorerStatus').textContent=e.message;}}
$('#explorerChoose').onclick=()=>void browse();$('#explorerUp').onclick=()=>void browse(parent);$('#explorerImport').onclick=()=>{if(!selected||exporting||historyBusy)return;historyCheckpoint();const e=selected,kind=/^(mp3|wav|aiff?|flac|m4a|aac|ogg)$/.test(e.extension)?'audio':'video';const card=addImportedCard({name:e.name,filePath:e.filePath},e.extension,kind);card.dataset.mediaType=kind==='audio'?'audio':/^(png|jpe?g|tiff|bmp|webp)$/.test(e.extension)?'image':'video';$('#mediaCount').textContent=$$('.media-card').length+' elementos';toast(e.name+' añadido a Project Media');};
for(const b of $$('.dock-panel-item')){const name=$('strong',b)?.textContent.trim(),target={'Project Media':'media',Explorer:'explorer',Generadores:'generators'}[name];if(target)b.addEventListener('click',e=>{e.stopImmediatePropagation();show(target);},true);else b.addEventListener('click',()=>{explorer.hidden=generators.hidden=true;clearPreview();});}
window.LQTACWorkspace={show,browse,get view(){return view;},generators};
})();
